// ─── Would be Account.java in a real project ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }

    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient funds in " + accountId);
        balance = balance.subtract(amount);
    }
    void credit(BigDecimal amount) { balance = balance.add(amount); }
}

// ─── Would be AccountRepository.java in a real project ───
class AccountRepository {
    private final java.util.Map<String, Account> db = new java.util.HashMap<>();
    AccountRepository() {
        db.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00")));
        db.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00")));
    }
    Account findById(String id) { return db.get(id); }
}

// ─── Would be TransferService.java in a real project ───
class TransferService {
    private static final Logger log = Logger.getLogger("BankLog");
    private final AccountRepository repo;
    TransferService(AccountRepository repo) { this.repo = repo; }

    void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = repo.findById(fromId);
        Account to = repo.findById(toId);
        log.info(() -> "Transfer " + amount + " from " + fromId + " to " + toId);
        from.debit(amount);
        to.credit(amount);
        log.info(() -> fromId + " new balance: " + from.getBalance());
        log.info(() -> toId + " new balance: " + to.getBalance());
    }
}
